# More detailed analysis

def analyze_game():
    """
    Detailed analysis of the apple game
    """

    def c_choice(A, B, R):
        """C's optimal choice given A, B, and remaining R"""
        # C wants to be strictly between A and B
        if A < B:
            # Want A < c < B
            if B - A >= 2:
                best_c = B - 1
                if best_c <= R and best_c > A:
                    return (best_c, True)  # (choice, satisfies_goal1)
        elif B < A:
            # Want B < c < A
            if A - B >= 2:
                best_c = A - 1
                if best_c <= R and best_c > B:
                    return (best_c, True)
        # Cannot satisfy Goal 1, take all remaining
        return (R, False)

    print("=" * 60)
    print("STEP-BY-STEP ANALYSIS")
    print("=" * 60)

    # Test A = 32
    A = 32
    print(f"\nIf A = {A}:")
    remaining_after_A = 100 - A

    # B's options
    best_for_B = None
    for B in range(0, remaining_after_A + 1):
        R = 100 - A - B
        C, c_sat = c_choice(A, B, R)

        values = [A, B, C]
        min_v, max_v = min(values), max(values)
        b_sat = (min_v < B < max_v)
        a_sat = (min_v < A < max_v)

        if B <= 5 or B >= remaining_after_A - 5 or (30 <= B <= 40):
            print(f"  B={B}: C takes {C}, final=({A},{B},{C}), B_goal1={b_sat}, A_goal1={a_sat}")

        # Track best for B
        if best_for_B is None:
            best_for_B = (B, b_sat, C)
        else:
            if best_for_B[1] and not b_sat:
                pass  # keep
            elif not best_for_B[1] and b_sat:
                best_for_B = (B, b_sat, C)
            elif b_sat and best_for_B[1]:
                if B > best_for_B[0]:
                    best_for_B = (B, b_sat, C)
            else:
                if B > best_for_B[0]:
                    best_for_B = (B, b_sat, C)

    print(f"  B's best choice: B={best_for_B[0]}, satisfies Goal1={best_for_B[1]}")

