            best_for_B = (B, b_sat, C)
        else:
            if best_for_B[1] and not b_sat:
                pass
            elif not best_for_B[1] and b_sat:
                best_for_B = (B, b_sat, C)
            elif b_sat and best_for_B[1]:
                if B > best_for_B[0]:
                    best_for_B = (B, b_sat, C)
            else:
                if B > best_for_B[0]:
                    best_for_B = (B, b_sat, C)

    print(f"  B's best choice: B={best_for_B[0]}, satisfies Goal1={best_for_B[1]}")

    # Test A = 34
    A = 34
    print(f"\nIf A = {A}:")
    remaining_after_A = 100 - A

    best_for_B = None
    for B in range(0, remaining_after_A + 1):
        R = 100 - A - B
        C, c_sat = c_choice(A, B, R)

        values = [A, B, C]
        min_v, max_v = min(values), max(values)
        b_sat = (min_v < B < max_v)

        if B <= 5 or B >= remaining_after_A - 5 or (30 <= B <= 40):
            print(f"  B={B}: C takes {C}, final=({A},{B},{C}), B_goal1={b_sat}")

        if best_for_B is None:
            best_for_B = (B, b_sat, C)
        else:
            if best_for_B[1] and not b_sat:
                pass
            elif not best_for_B[1] and b_sat:
                best_for_B = (B, b_sat, C)
            elif b_sat and best_for_B[1]:
                if B > best_for_B[0]:
                    best_for_B = (B, b_sat, C)
            else:
                if B > best_for_B[0]:
                    best_for_B = (B, b_sat, C)

    print(f"  B's best choice: B={best_for_B[0]}, satisfies Goal1={best_for_B[1]}")

    # Now full solution
    print("\n" + "=" * 60)
    print("FULL SOLUTION")
    print("=" * 60)

    best_overall = None
    for A in range(0, 101):
        remaining_after_A = 100 - A

        # Find B's best response
        best_for_B = None
