                elif not best_for_B[1] and b_sat:
                    best_for_B = (B, b_sat, C)
                elif b_sat and best_for_B[1]:
                    if B > best_for_B[0]:
                        best_for_B = (B, b_sat, C)
                else:
                    if B > best_for_B[0]:
                        best_for_B = (B, b_sat, C)

        B, b_sat, C = best_for_B
        values = [A, B, C]
        min_v, max_v = min(values), max(values)
        a_sat = (min_v < A < max_v)

        # Only print interesting cases
        if A in [30, 31, 32, 33, 34, 35, 50]:
            print(f"A={A}: B chooses {B}, C={C}, final=({A},{B},{C}), A_goal1={a_sat}, B_goal1={b_sat}")

        if best_overall is None:
            best_overall = (A, B, C, a_sat)
        else:
            curr_A, curr_B, curr_C, curr_a_sat = best_overall
            if curr_a_sat and not a_sat:
                pass
            elif not curr_a_sat and a_sat:
                best_overall = (A, B, C, a_sat)
            elif a_sat and curr_a_sat:
                if A > curr_A:
                    best_overall = (A, B, C, a_sat)
            else:
                if A > curr_A:
                    best_overall = (A, B, C, a_sat)

    print(f"\nOPTIMAL: A={best_overall[0]}, B={best_overall[1]}, C={best_overall[2]}")
    print(f"A satisfies Goal 1: {best_overall[3]}")

